const genreArtwork={"Ballad":"/assets/genres/04.webp","Dark Pop":"/assets/genres/03.webp","Soul":"/assets/genres/06.webp","R&B":"/assets/genres/05.webp","Hip-Hop":"/assets/genres/07.webp","Rock":"/assets/genres/08.webp","Alternative":"/assets/genres/09.webp","Indie Pop":"/assets/genres/10.webp","K-POP":"/assets/genres/01.webp","Pop":"/assets/genres/02.webp","EDM":"/assets/genres/11.webp","Electronic":"/assets/genres/12.webp","Synth Pop":"/assets/genres/13.webp","City Pop":"/assets/genres/14.webp","Lo-fi":"/assets/genres/15.webp","Jazz":"/assets/genres/16.webp","Blues":"/assets/genres/17.webp","Folk":"/assets/genres/18.webp","Acoustic":"/assets/genres/19.webp","Country":"/assets/genres/20.webp","Classical":"/assets/genres/21.webp","Ambient":"/assets/genres/22.webp","Fusion":"/assets/genres/23.webp","Korean Folklore Fusion":"/assets/genres/24.webp","World Music":"/assets/genres/25.webp","국악":"/assets/genres/26.webp","트로트":"/assets/genres/27.webp","J-POP":"/assets/genres/28.webp","OST":"/assets/genres/29.webp","Instrumental":"/assets/genres/30.webp","Dance":"/assets/genres/31.webp","Funk":"/assets/genres/32.webp","Disco":"/assets/genres/33.webp","Metal":"/assets/genres/34.webp","Punk":"/assets/genres/35.webp","Reggae":"/assets/genres/36.webp","Latin":"/assets/genres/37.webp","Reggaeton":"/assets/genres/38.webp","Afrobeats":"/assets/genres/39.webp","House":"/assets/genres/40.webp","Techno":"/assets/genres/41.webp","Trance":"/assets/genres/42.webp","Drum & Bass":"/assets/genres/43.webp","Trap":"/assets/genres/44.webp","Gospel":"/assets/genres/45.webp","New Age":"/assets/genres/46.webp","Chillout":"/assets/genres/47.webp","Cinematic":"/assets/genres/48.webp","Orchestral":"/assets/genres/49.webp","Children":"/assets/genres/50.webp"};
function genreCardHTML(g){return `<a class="genre-photo-card" href="#discover/genres?g=${encodeURIComponent(g)}"><img src="${esc(genreArtwork[g])}" alt="" loading="lazy" decoding="async"><span><small>EXPLORE MUSIC</small><strong>${esc(g)}</strong></span>${icon('chevron')}</a>`;}
function chartMovementHTML(t){
 const state=t.chart_movement,delta=Math.abs(Number(t.rank_change)||0),labels={up:`어제보다 ${delta}위 상승`,down:`어제보다 ${delta}위 하락`,same:'어제와 같은 순위',new:'새롭게 차트 진입',unavailable:'전날 비교 기록 없음'},label=labels[state]||labels.unavailable;
 return `<div class="chart-score chart-movement ${Object.hasOwn(labels,state)?state:'unavailable'}" aria-label="${label}" title="${label}"><strong aria-hidden="true">${state==='up'?'↑ '+delta:state==='down'?'↓ '+delta:state==='new'?'NEW':'—'}</strong></div>`;
}
// Shared navigation for listening, singing and the community on desktop and mobile.
function updateBrowseNavigation(base,param){
 const primary=['karaoke','sing','cover'].includes(base)?'karaoke':['community','covers','crew','producer','artist','following'].includes(base)?'community':base==='dm'?'dm':base==='notifications'?'notifications':['inventory','profile','account','studio','manage','upload','payouts','rewards'].includes(base)?'profile':['library','history'].includes(base)?'home':'home';
 const routeHref='#'+base+(param?'/'+param:''),hasSidebarPage=[...document.querySelectorAll('.sidebar .nav-link[data-view]:not([data-primary-view])')].some(a=>a.getAttribute('href')===routeHref);
 document.querySelectorAll('[data-primary-view]').forEach(a=>{const inSidebar=!!a.closest('.sidebar'),active=!(inSidebar&&hasSidebarPage)&&a.dataset.primaryView===(inSidebar&&['library','history'].includes(base)?'library':primary);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 document.querySelectorAll('.nav-link[data-view]:not([data-primary-view])').forEach(a=>{const active=a.getAttribute('href')==='#'+base+(param?'/'+param:'');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
}
function chartTabs(active=''){return `<nav class="tabs" aria-label="차트 종류">${[['','인기 차트'],['karaoke','노래방 차트'],['rising','급상승'],['newcomers','신인'],['releases','최신 음악']].map(([key,label])=>`<a class="tab ${active===key?'active':''}" href="#charts${key?'/'+key:''}" ${active===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function libraryTabs(active='likes'){if(['artists','producers'].includes(active))active='following';return `<nav class="tabs" aria-label="보관함 종류">${[['likes','좋아요'],['playlists','플레이리스트'],['history','최근 들은 곡'],['covers','내 커버곡'],['originals','내 제작곡'],['following','팔로잉'],['followers','팔로워']].map(([key,label])=>`<a class="tab ${active===key?'active':''}" href="#library/${key}" ${active===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function browsePlaybackActions(tracks,showCount=true){return `<div class="inline-actions playlist-actions"><button class="primary-button" data-play-all ${tracks.length?'':'disabled'}>${icon('play')} 전체 듣기</button><button class="small-button" data-browse-shuffle ${tracks.length?'':'disabled'}>${icon('shuffle')} 섞어 듣기</button>${showCount?`<span class="field-help" data-browse-count>${tracks.length}곡</span>`:''}</div>`;}
function browseQuickLinks(){return `<nav class="browse-shortcuts" aria-label="음악 즐기기"><a href="#charts">${icon('chart')}<strong>인기 차트</strong></a><a href="#charts/karaoke">${icon('mic')}<strong>노래방 차트</strong><small>듣고, 직접 부르고</small></a><a href="#community/covers">${icon('users')}<strong>커버곡 둘러보기</strong><small>같은 곡, 다른 목소리</small></a><a href="#collections">${icon('library')}<strong>공개 플레이리스트</strong><small>취향을 나누는 선곡</small></a></nav>`;}
function browseSearchHTML(){return `<section class="discovery-search-hero">${heading('발견','지금의 기분에서, 다음 취향까지.')}<form id="search-form" class="aifect-search" role="search">${icon('search')}<input type="search" name="q" aria-label="곡, 아티스트, 제작자 검색" placeholder="곡, 아티스트, 제작자, 플레이리스트" maxlength="100"><button class="primary-button">검색</button></form><p class="field-help">제목이나 이름을 검색하거나, 아래에서 마음이 가는 음악을 골라보세요.</p></section>`+section('어디서부터 들어볼까요?')+browseQuickLinks()+`<section class="discovery-mood-panel">${section('오늘, 어떤 기분인가요?')}<div class="genre-chips">${moodOptions.map(([key,label])=>`<a class="genre-chip" href="#discover/mood?m=${key}">${esc(label)}</a>`).join('')}</div></section>`+section('장르 둘러보기')+`<div class="browse-genres">${genres.filter(g=>g!=='전체').map(genreCardHTML).join('')}</div><a class="genre-photo-credits" href="/assets/genres/credits.html" target="_blank" rel="noopener">이미지 출처</a>`;}
function chartLayoutHTML(content,tracks,kind=''){
 const t=tracks[0],isCover=kind==='karaoke';
 return `<div class="chart-page-layout"><section class="chart-page-results" aria-label="음악 목록">${kind==='releases'||isCover?`<div class="chart-list-heading"><h2>${isCover?'우리들의 커버곡':'새로 공개된 곡'}</h2></div>`:''}${content}</section><aside class="chart-page-aside">${t?`<section class="chart-spotlight"><span class="eyebrow">${kind==='releases'?'JUST RELEASED':isCover?'COVER SPOTLIGHT':'ON THE CHART'}</span><a href="#song/${esc(t.id)}" aria-label="${esc(t.title)} 곡 정보">${cover(t,'chart-feature-art')}</a><h2><a href="#song/${esc(t.id)}">${esc(t.title)}</a></h2><p>${credits(t)}</p><button class="primary-button" data-play="${esc(t.id)}">${icon('play')} 지금 듣기</button></section>`:''}<section class="chart-invitation"><span class="eyebrow">YOUR NEXT FAVORITE</span><h3>${isCover?'다음 목소리는 당신의 차례.':'듣다 보면, 부르고 싶어지는.'}</h3><p>좋아하는 음악에 나만의 목소리를 더해보세요.</p><a class="small-button" href="#karaoke">${icon('mic')} 부를 곡 찾기 ${icon('arrow')}</a></section><nav class="chart-explore-links" aria-label="다른 음악 발견"><a href="#search">${icon('compass')} 기분 · 장르로 찾기 ${icon('chevron')}</a><a href="#collections">${icon('library')} 공개 플레이리스트 ${icon('chevron')}</a></nav></aside></div>`;
}
function karaokeRows(tracks,ranked=false){return tracks.length?`<div class="karaoke-browse-list">${tracks.map((t,i)=>`<article class="karaoke-browse-row">${ranked?`<span class="browse-rank">${t.browseRank||i+1}</span>`:''}<a href="#song/${esc(t.id)}" aria-label="${esc(t.title)} 곡 정보">${cover(t,'mini-cover')}</a><div class="karaoke-browse-info"><a href="#song/${esc(t.id)}"><strong>${esc(t.title)}</strong></a><span>${credits(t)}</span><small>${esc(t.genre)} · ${time(t.duration)} · MR 제공</small>${trackStats(t)}${karaokeParticipationHTML(t)}</div><div class="karaoke-browse-actions"><button class="small-button" data-play="${esc(t.id)}" aria-label="${esc(t.title)} 원곡 듣기">${icon('play')} 원곡 듣기</button><a class="text-link" href="#community/rankings?period=all&amp;original_id=${esc(t.id)}">커버 랭킹</a><a class="small-button" href="#sing/${esc(t.id)}">${icon('mic')} 부르기</a><a class="text-link" href="#cover/${esc(t.id)}">녹음 파일 올리기</a></div><div class="karaoke-cover-results" id="covers-${esc(t.id)}" hidden></div></article>`).join('')}</div>`:empty('아직 부를 수 있는 곡이 없어요.','MR이 준비되고 원곡자가 커버를 허락한 곡이 여기에 표시돼요.','#community/covers','다른 사람의 커버 둘러보기');}
function communityPeopleStrip(tracks){const seen=new Set(),people=[];for(const t of tracks){const id=t.producer_id,name=t.producer;if(!id||!name||seen.has(id))continue;seen.add(id);people.push({id,name,image_version:t.producer_image_version,kind:t.kind,cover_mode:t.cover_mode});if(people.length>=10)break;}return people.length?`<section class="community-people"><div class="community-people-heading"><div><h2>새로운 목소리</h2><p>최근 커버나 신곡을 올린 사람들의 프로필을 만나보세요.</p></div><a href="#following">팔로잉 보기</a></div><div class="community-people-row">${people.map(p=>`<a href="#producer/${esc(p.id)}"><span class="community-person-avatar profile-avatar">${avatarImage(p)}</span><strong>${esc(p.name)}</strong><small>${p.kind==='cover'?(p.cover_mode==='duet'?'듀엣 공개':'커버 공개'):'신곡 공개'}</small></a>`).join('')}</div></section>`:'';}
function communityFeed(tracks){return tracks.length?'<div class="music-feed">'+tracks.map(t=>musicTrackCard(t)).join('')+'</div>':empty('아직 공개된 음악이 없어요.','다른 음악을 둘러보거나 첫 곡을 들려주세요.','#karaoke','부를 곡 찾기');}
async function popularChartView(raw=''){
 const query=new URLSearchParams(raw.includes('?')?raw.split('?')[1]:''),period=query.get('period')||'week';
 const d=await api('/api/catalog?section=tracks&chart=top&period='+encodeURIComponent(period));
 const chart=d.chart,tracks=d.tracks;
 const periods=[['today','오늘'],['week','이번 주'],['month','이달'],['all','명예의 전당']];
 const periodsHTML='<nav class="tabs" aria-label="인기차트 기간">'+periods.map(([key,label])=>'<a class="tab '+(period===key?'active':'')+'" href="#charts?period='+key+'" '+(period===key?'aria-current="page"':'')+'>'+label+'</a>').join('')+'</nav>';
 const criteria='';
 const rows=songTable(tracks,{chart:true});
 return {html:heading('AIFECT 인기차트','함께 듣고, 좋아하고, 응원한 음악의 순위.')+chartTabs()+chartLayoutHTML(periodsHTML+criteria+'<p class="field-help">'+esc(chart?.label||'이번 주')+' · 한국 시간 기준 · 어제 집계 대비</p>'+(chart?.comparison?.available?'':'<p class="field-help chart-comparison-note">전날 순위 기록이 준비되면 변동을 표시해요.</p>')+browsePlaybackActions(tracks)+(tracks.length?rows:empty('아직 공개된 곡이 없어요.','새로운 음악이 올라오면 여기서 만나요.')),tracks),tracks};
}
async function browseView(base,param,raw){
 if(base==='charts'&&(!param||param==='top'))return popularChartView(raw);
 if(base==='search'&&!param)return {html:browseSearchHTML()};
 if(base==='charts'&&param==='karaoke'||base==='karaoke'&&param==='chart'){
  const d=await api('/api/cover-rankings?kind=tracks&period=week&include_unranked=1'),tracks=d.tracks.filter(t=>t.kind==='cover');
  return {html:heading('노래방 차트','공개된 커버곡만 모았어요. 이번 주 받은 좋아요 순으로 만나요.')+chartTabs('karaoke')+chartLayoutHTML(browsePlaybackActions(tracks)+(tracks.length?coverRankTracksHTML(tracks):empty('아직 등록된 커버곡이 없어요','첫 커버곡이 공개되면 이곳에서 만날 수 있어요.','#karaoke','노래 부르기')),tracks,'karaoke'),tracks};
 }
 if(base==='karaoke'&&param==='drafts'){if(!me){returnRoute=location.hash;return {html:gate()};}return {html:karaokeDraftsHTML(await listSingDrafts())};}
 if(base==='karaoke'){
  const [d,duets]=await Promise.all([api('/api/karaoke'),api('/api/duets')]),tracks=d.tracks.map((t,i)=>({...t,browseRank:i+1}));
  remember([...(d.recent_covers||[]),...duets.tracks]);return {html:singingHubHTML(tracks,d.recent_covers||[],duets.tracks),tracks,karaokeTracks:tracks,singingHub:true};
 }
 if(base==='community'||base==='covers')return communityView(base,param,raw);
 if(base==='history'||base==='library'&&['history','covers','originals','following'].includes(param)){
  if(!me){returnRoute=location.hash;return {html:gate()};}
  const tab=base==='history'?'history':param;let html=heading('내 보관함','좋아하는 음악과 내가 남긴 목소리를 한곳에서.')+libraryTabs(tab);
  if(tab==='following'){await refreshLibrary();const people=kind=>library.follows.filter(f=>f.kind===kind).map(f=>({...f,id:f.target_id}));html+=`<p class="field-help"><a class="text-link" href="#community/following">팔로우한 창작자의 새 음악 듣기</a></p>`;for(const [kind,title] of [['producer','창작자'],['artist','AI 아티스트']])html+=section(title)+(people(kind).length?peopleListHTML(people(kind),kind):`<p class="empty-inline">아직 팔로우한 ${title}가 없어요. <a class="text-link" href="#${kind==='producer'?'producers':'artists'}">둘러보기</a></p>`);return {html};}
  if(tab==='history'){const d=await api('/api/history');return {html:html+browsePlaybackActions(d.tracks)+list(d.tracks),tracks:d.tracks};}
  const d=await api('/api/studio'),owned=d.tracks.filter(t=>t.kind===(tab==='covers'?'cover':'original')),published=owned.filter(t=>t.status==='published');
  html+=`<div class="inline-actions playlist-actions"><a class="primary-button" href="#${tab==='covers'?'karaoke':'upload'}">${icon('plus')} ${tab==='covers'?'새 커버곡 부르기':'제작곡 올리기'}</a><a class="text-link" href="#studio">스튜디오에서 관리</a></div>`;
  html+=tab==='covers'&&owned.length?coverCollectionHTML(owned,'my-covers',true):owned.length?`<div class="own-music-list">${owned.map(t=>`<article class="own-music-row">${cover(t,'mini-cover')}<div><strong>${esc(t.title)}</strong><small>${esc(({published:'공개 중',draft:'작성 중',processing:'음원 처리 중',hidden:'비공개',failed:'처리 실패'})[t.status]||'준비 중')}</small></div>${t.status==='published'?`<button class="icon-button" data-play="${esc(t.id)}" aria-label="${esc(t.title)} 듣기">${icon('play')}</button>`:''}<a class="small-button" href="#manage/${esc(t.id)}">관리</a></article>`).join('')}</div>`:empty(tab==='covers'?'아직 내 커버곡이 없어요.':'아직 내 제작곡이 없어요.','좋아하는 음악으로 나만의 이야기를 시작해보세요.',tab==='covers'?'#karaoke':'#upload',tab==='covers'?'부를 곡 찾아보기':'음악 올리기');
  return {html,tracks:published};
 }
 return null;
}
function bindBrowse(view){
 bindCommunity(view);
 const results=$('#karaoke-results');if(results)results.addEventListener('click',async e=>{
  const button=e.target.closest('[data-karaoke-covers]');if(!button)return;
  const panel=document.getElementById(button.getAttribute('aria-controls')),uid=me?.id;
  if(!panel)return;
  if(!panel.hidden){panel.hidden=true;button.setAttribute('aria-expanded','false');return;}
  panel.hidden=false;button.setAttribute('aria-expanded','true');
  if(panel.dataset.loaded)return;
  button.disabled=true;panel.innerHTML='<p role="status">참여 커버를 불러오는 중…</p>';
  try{const d=await api('/api/tracks/'+encodeURIComponent(button.dataset.karaokeCovers)+'/covers?sort=recent');
   if(!panel.isConnected||uid!==me?.id)return;remember(d.covers);
   panel.innerHTML=d.covers.length?'<h3>이 곡에 참여한 커버</h3><div class="karaoke-participant-list">'+d.covers.map(t=>'<article><a href="#song/'+esc(t.id)+'">'+cover(t,'mini-cover')+'</a><div><a href="#song/'+esc(t.id)+'"><strong>'+esc(t.title)+'</strong></a><a href="#producer/'+esc(t.producer_id)+'">'+esc(t.producer)+'</a><small>'+musicKind(t)+' · '+number(t.plays||0)+'회 감상</small></div><button class="small-button" data-play="'+esc(t.id)+'" aria-label="'+esc(t.producer)+'의 커버 듣기">'+icon('play')+' 듣기</button></article>').join('')+'</div>':'<p>아직 참여한 커버가 없어요. 첫 목소리를 남겨보세요.</p>';
   panel.dataset.loaded='1';
  }catch(error){if(panel.isConnected)panel.innerHTML='<p role="alert">'+esc(error.message)+' 접었다 다시 누르면 재시도할 수 있어요.</p>';}
  finally{button.disabled=false;}
 });
 if(view?.singingHub){bindSingingHub(view);return;}
 const search=$('#karaoke-search');if(search)search.oninput=()=>{const q=search.value.trim().toLocaleLowerCase(),items=view.karaokeTracks.filter(t=>[t.title,t.artist,t.producer].join(' ').toLocaleLowerCase().includes(q));routeTracks=items;$('#karaoke-count').textContent=items.length+'곡';document.querySelectorAll('[data-browse-count]').forEach(el=>el.textContent=items.length+'곡');$('#karaoke-results').innerHTML=items.length?karaokeRows(items,view.ranked):'<p class="empty-inline">일치하는 곡이 없어요. 다른 제목이나 창작자 이름을 검색해보세요.</p>';document.querySelectorAll('[data-play-all],[data-browse-shuffle]').forEach(b=>b.disabled=!items.length);};
 const button=$('[data-browse-shuffle]');if(button)button.onclick=async()=>{const tracks=[...routeTracks];for(let i=tracks.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[tracks[i],tracks[j]]=[tracks[j],tracks[i]];}if(tracks.length)try{await play(tracks[0].id,tracks);}catch(e){toast(e.message);}};
}

let homeBrowseObserver=null;
